#pragma CODE_SECTION(zvs_t2_axis_index, ".TI.ramfunc");
static uint16_t zvs_t2_axis_index(float x, const float *axis,
                                     uint16_t n, float *fraction)
{
    uint16_t low_index;
    uint16_t high_index;
    uint16_t mid;

    if (x <= axis[0]) { *fraction = 0.0F; return 0U; }
    if (x >= axis[n - 1U]) { *fraction = 1.0F; return (uint16_t)(n - 2U); }
    low_index = 0U;
    high_index = (uint16_t)(n - 1U);
    while ((uint16_t)(high_index - low_index) > 1U) {
        mid = (uint16_t)(((uint32_t)low_index + (uint32_t)high_index) / 2UL);
        if (x < axis[mid]) high_index = mid;
        else low_index = mid;
    }
    *fraction = (x - axis[low_index]) /
                 (axis[high_index] - axis[low_index]);
    return low_index;
}

#pragma CODE_SECTION(zvs_t2_sample, ".TI.ramfunc");
static float zvs_t2_sample(uint16_t iv, uint16_t io, uint16_t ii)
{
    uint32_t index;
    uint16_t code;
    index = ((uint32_t)iv * (uint32_t)ZVS_T2_N_VO + (uint32_t)io) *
            (uint32_t)ZVS_T2_N_ICMD + (uint32_t)ii;
    code = zvs_t2_table[index];
    if (code == ZVS_T2_INVALID_CODE) return ZVS_T2_INVALID;
    return (float)code / ZVS_T2_VALUE_SCALE;
}

#pragma CODE_SECTION(zvs_t2_accumulate, ".TI.ramfunc");
static void zvs_t2_accumulate(float value, float weight,
                               float *sum, float *weight_sum)
{
    if ((weight > 0.0F) && (value != ZVS_T2_INVALID)) {
        *sum += value * weight;
        *weight_sum += weight;
    }
}

float ZVS_T2_GetByIndex(uint16_t vin_index, uint16_t vo_index,
                        uint16_t icmd_index)
{
    if ((vin_index >= ZVS_T2_N_VIN) || (vo_index >= ZVS_T2_N_VO) ||
        (icmd_index >= ZVS_T2_N_ICMD)) return ZVS_T2_INVALID;
    return zvs_t2_sample(vin_index, vo_index, icmd_index);
}

#pragma CODE_SECTION(ZVS_T2_Lookup, ".TI.ramfunc");
float ZVS_T2_Lookup(float vin_v, float vo_v, float icmd_a)
{
    uint16_t iv;
    uint16_t io;
    uint16_t ii;
    float fv;
    float fo;
    float fi;
    float sum = 0.0F;
    float weight_sum = 0.0F;

    if ((vin_v != vin_v) || (vo_v != vo_v) || (icmd_a != icmd_a))
        return ZVS_T2_INVALID;
    iv = zvs_t2_axis_index(vin_v, zvs_t2_vin_axis, ZVS_T2_N_VIN, &fv);
    io = zvs_t2_axis_index(vo_v, zvs_t2_vo_axis, ZVS_T2_N_VO, &fo);
    ii = zvs_t2_axis_index(icmd_a, zvs_t2_icmd_axis, ZVS_T2_N_ICMD, &fi);

    zvs_t2_accumulate(zvs_t2_sample(iv, io, ii),
                      (1.0F - fv) * (1.0F - fo) * (1.0F - fi),
                      &sum, &weight_sum);
    zvs_t2_accumulate(zvs_t2_sample(iv, io, ii + 1U),
                      (1.0F - fv) * (1.0F - fo) * fi, &sum, &weight_sum);
    zvs_t2_accumulate(zvs_t2_sample(iv, io + 1U, ii),
                      (1.0F - fv) * fo * (1.0F - fi), &sum, &weight_sum);
    zvs_t2_accumulate(zvs_t2_sample(iv, io + 1U, ii + 1U),
                      (1.0F - fv) * fo * fi, &sum, &weight_sum);
    zvs_t2_accumulate(zvs_t2_sample(iv + 1U, io, ii),
                      fv * (1.0F - fo) * (1.0F - fi), &sum, &weight_sum);
    zvs_t2_accumulate(zvs_t2_sample(iv + 1U, io, ii + 1U),
                      fv * (1.0F - fo) * fi, &sum, &weight_sum);
    zvs_t2_accumulate(zvs_t2_sample(iv + 1U, io + 1U, ii),
                      fv * fo * (1.0F - fi), &sum, &weight_sum);
    zvs_t2_accumulate(zvs_t2_sample(iv + 1U, io + 1U, ii + 1U),
                      fv * fo * fi, &sum, &weight_sum);

    if (weight_sum < 0.999999F) return ZVS_T2_INVALID;
    return sum / weight_sum;
}

float ZVS_T2_LookupSeconds(float vin_v, float vo_v, float icmd_a)
{
    float normalized = ZVS_T2_Lookup(vin_v, vo_v, icmd_a);
    if (normalized == ZVS_T2_INVALID) return ZVS_T2_INVALID;
    return normalized * ZVS_T2_SWITCH_PERIOD_S;
}
